mapper.update:
UPDATE t_detect
SET title = #{title}
WHERE id = #{id}

UPDATE t_detect
SET status = #{status}
WHERE id = #{id}

mapper.insert:
INSERT OR REPLACE INTO t_detect_node (
  master_id, parent_id, depth, url, path_segment, title, http_status, has_violation, violation_cnt, created_at
) VALUES (
  #{master_id}, #{parent_id}, #{depth}, #{url}, #{path_segment}, #{title}, #{http_status}, #{has_violation}, #{violation_cnt},
  datetime('now', 'localtime')
)

mapper.select:
SELECT master_id, finding_id, target_text, clean_title, clean_body, updated_at
FROM t_detect_solution
WHERE master_id = #{master_id} AND finding_id = #{finding_id}

SELECT finding_id FROM t_detect_list
WHERE master_id = #{master_id} AND finding_id = #{finding_id}
LIMIT 1

SELECT DISTINCT url
FROM (
  SELECT url FROM t_detect_node WHERE master_id = #{master_id}
  UNION ALL
  SELECT url FROM t_detect_list WHERE master_id = #{master_id}
) AS history_urls
WHERE url IS NOT NULL AND TRIM(url) != ''

SELECT COUNT(*) AS total_count FROM t_detect WHERE 1=1
AND (entry_url LIKE '%' || #{keyword} || '%' OR title LIKE '%' || #{keyword} || '%')
AND status = #{statusFilter}

SELECT t.id, t.entry_url, t.title, t.status, t.started_at, t.finished_at, CASE WHEN t.elapsed_sec > 0 THEN t.elapsed_sec ELSE COALESCE(MAX(0, CAST(ROUND((julianday(t.finished_at) - julianday(t.started_at)) * 86400) AS INTEGER)), 0) END AS elapsed_sec, t.total_pages, (SELECT COUNT(*) FROM (SELECT f.url, f.location, f.technique FROM t_detect_list f WHERE f.master_id = t.id GROUP BY f.url, f.location, f.technique)) AS violation_count, t.tool_version, t.created_at FROM t_detect t WHERE 1=1
AND (t.entry_url LIKE '%' || #{keyword} || '%' OR t.title LIKE '%' || #{keyword} || '%')
AND t.status = #{statusFilter}
ORDER BY t.id DESC LIMIT #{limit} OFFSET #{offset}
